import { useEffect, useState } from "react";
import api, { apiErrorMessage } from "../lib/api";
import { useAuth } from "../context/AuthContext";
import { useContent } from "../context/ContentContext";
import { Trophy, Crown, Medal, Star, X } from "lucide-react";
import Avatar from "../components/Avatar";
import KingCelebration from "../components/KingCelebration";

export default function Leaderboard() {
  const { user } = useAuth();
  const { t } = useContent();
  const [marquee,setMarquee]=useState("🏆 الرعاة الرسميون لجائزة ملك التوقعات");
  const [rows, setRows] = useState([]);
  const [loading, setLoading] = useState(true);
  const [progress, setProgress] = useState(100);

  
useEffect(() => {
  api.get("/marquee")
    .then(r=>setMarquee(r.data?.text || ""))
    .catch(()=>{});
}, []);

useEffect(() => {
    (async () => {
      try {
        const { data } = await api.get("/leaderboard");
        setRows(data);
      } catch (e) {
        console.error(apiErrorMessage(e));
      } finally {
        setLoading(false);
      }
    })();
  }, []);



  const podium = rows.slice(0, 3);
  const rest = rows.slice(3);

  return (
    <div className="max-w-5xl mx-auto px-4 sm:px-6 lg:px-8 py-10 pb-28" data-testid="leaderboard-page">

      <KingCelebration leader={rows[0]} />


      <div className="sticky top-16 z-40 mb-6 border border-gold/20 bg-black/95 backdrop-blur rounded-2xl overflow-hidden shadow-[0_0_25px_rgba(255,215,0,0.15)]">
        <div className="relative h-12 flex items-center overflow-hidden">
          <div className="whitespace-nowrap text-gold font-black text-sm sm:text-base" style={{ animation: "leaderboardMarquee 18s linear infinite" }}>
            {marquee}
          </div>
        </div>
        <style>
          {"@keyframes leaderboardMarquee { 0% { transform: translateX(-100%); } 100% { transform: translateX(100%); } }"}
        </style>
      </div>

      <div className="text-center mb-12">
        <div className="inline-flex items-center justify-center w-20 h-20 rounded-full bg-gold/10 border border-gold/20 mb-5 shadow-[0_0_35px_rgba(255,215,0,0.16)]">
          <Trophy className="w-10 h-10 text-gold" />
        </div>
        <p className="text-xs font-bold text-gold uppercase tracking-[0.2em] mb-2">
          {t("leaderboard_pretitle")}
        </p>
        <h1 className="font-display text-4xl sm:text-5xl font-black mb-3">
          {t("leaderboard_title")}
        </h1>
        <p className="text-zinc-400 max-w-xl mx-auto">
          {t("leaderboard_desc")}
        </p>
        <p className="text-xs text-zinc-500 max-w-xl mx-auto mt-3">
          الترتيب: النقاط أولاً، ثم عدد النتائج الدقيقة 🎯، ثم الأسبق بالتوقع
        </p>
      </div>

      {loading ? (
        <div className="space-y-3">
          {Array.from({ length: 8 }).map((_, i) => (
            <div key={i} className="skeleton h-16 rounded-xl" />
          ))}
        </div>
      ) : rows.length === 0 ? (
        <div className="glass-card rounded-2xl p-16 text-center">
          <p className="text-zinc-400">لا يوجد متسابقون بعد. كن الأول!</p>
        </div>
      ) : (
        <>
          {podium.length > 0 && (
            <div className="grid grid-cols-3 gap-3 sm:gap-6 mb-10 items-end">
              {[1, 0, 2].map((i) => {
                const r = podium[i];
                if (!r) return <div key={i} />;

                const isFirst = r.rank === 1;
                const isSecond = r.rank === 2;
                const isThird = r.rank === 3;

                return (
                  <div
                    key={r.user_id}
                    data-testid={`podium-${r.rank}`}
                    className={`relative rounded-3xl text-center border overflow-visible ${
                      isFirst
                        ? "bg-gradient-to-b from-gold/22 to-white/[0.03] border-gold/60 p-4 sm:p-5 sm:scale-105 sm:-translate-y-3 shadow-[0_0_45px_rgba(255,215,0,0.28)] animate-[kingGlow_2.4s_ease-in-out_infinite]"
                        : isSecond
                        ? "bg-gradient-to-b from-zinc-200/10 to-white/[0.03] border-zinc-300/35 p-4 sm:p-5"
                        : "bg-gradient-to-b from-amber-700/15 to-white/[0.03] border-amber-700/40 p-4 sm:p-5"
                    }`}
                  >
                    <div className="absolute -top-6 left-1/2 -translate-x-1/2">
                      <div
                        className={`w-12 h-12 rounded-full flex items-center justify-center border shadow-xl ${
                          isFirst
                            ? "bg-gold text-black border-yellow-200 shadow-[0_0_28px_rgba(255,215,0,0.6)]"
                            : isSecond
                            ? "bg-zinc-200 text-black border-white"
                            : "bg-amber-700 text-white border-amber-400"
                        }`}
                      >
                        {isFirst ? (
                          <Crown className="w-7 h-7" />
                        ) : isSecond ? (
                          <Medal className="w-7 h-7" />
                        ) : (
                          <Star className="w-7 h-7" />
                        )}
                      </div>
                    </div>

                    <div className="pt-6">
                      <div className={`mx-auto mb-3 rounded-full inline-block ${
                        isFirst
                          ? "ring-4 ring-gold shadow-[0_0_25px_rgba(255,215,0,0.35)]"
                          : isSecond
                          ? "ring-2 ring-zinc-300"
                          : "ring-2 ring-amber-700"
                      }`}>
                        <Avatar src={r.avatar} name={r.name} size={60} />
                      </div>

                      <p className="text-xs text-zinc-400 mb-1">المركز {r.rank}</p>

                      <p className="font-black text-sm sm:text-base leading-6 mb-2 whitespace-normal break-words min-h-[48px] flex items-center justify-center px-1">
                        {r.name}
                      </p>

                      <p className="font-display text-3xl font-black text-gold leading-none">
                        {r.total_points}
                      </p>

                      <p className="text-xs text-zinc-500 mt-2">
                        {r.predictions_count} توقع
                      </p>

                      {r.exact_count > 0 && (
                        <p className="text-[11px] text-gold/90 mt-1 font-bold leading-5">
                          🎯 {r.exact_count} نتيجة دقيقة
                        </p>
                      )}
                    </div>
                  </div>
                );
              })}
            </div>
          )}

          {rest.length > 0 && (
            <div className="glass-card rounded-3xl overflow-hidden border border-white/10">
              {rest.map((r) => {
                const isMe = user && r.user_id === user.id;

                return (
                  <div
                    key={r.user_id}
                    data-testid={`leaderboard-row-${r.rank}`}
                    className={`flex items-center justify-between gap-3 p-4 border-b border-white/5 last:border-0 ${
                      isMe ? "bg-gold/10 border-r-4 border-r-gold" : ""
                    }`}
                  >
                    <div className="flex items-center gap-3 min-w-0 flex-1">
                      <span className="font-display font-black text-lg text-zinc-400 w-8 text-center shrink-0">
                        {r.rank}
                      </span>

                      <Avatar src={r.avatar} name={r.name} size={42} />

                      <div className="min-w-0 flex-1">
                        <p className="font-bold text-base whitespace-normal break-words leading-6">
                          {r.name}
                          {isMe && <span className="text-xs text-gold mr-2">(أنت)</span>}
                        </p>
                        <p className="text-xs text-zinc-500 leading-5">
                          {r.predictions_count} توقع
                          {r.exact_count > 0 && (
                            <span className="mx-2 text-gold/80">• 🎯 {r.exact_count} دقيق</span>
                          )}
                        </p>
                      </div>
                    </div>

                    <div className="font-display font-black text-2xl text-gold shrink-0">
                      {r.total_points}
                    </div>
                  </div>
                );
              })}
            </div>
          )}
        </>
      )}

      {/* النافذة المنبثقة التكريمية لملك التوقعات الحالي */}
      

    </div>
  );
}
